      case Seq(1, _) => // ok
    }

    // Containment check
    "hello world" shouldContain "world"
    Seq(1, 2, 3) shouldContain 1

    "hello world" shouldNotContain "!!"
    Seq(1, 2, 3) shouldNotContain 4
