  renderLoading();
  db.subscribeAuth((auth) => {
    if (auth.error) {
      renderAuthError(auth.error.message);
    } else if (auth.user) {
      renderLoggedInPage(auth.user);
    } else {
      renderSignInPage();
    }
  });
}
