    if (!lightdashConfig.license.licenseKey) {
        return {};
    }

    // License validation...

    return {
        serviceProviders: {
            embedService: ({ repository, context, models }) =>
                new EmbedService({
                    // dependencies...
                }),
            aiService: ({ repository, context, models }) =>
                new AiService({
                    // dependencies...
                }),
            // Other service providers...
        },
        modelProviders: {
            embedModel: ({ database }) =>
                new EmbedModel({
                    database,
                }),
            // Other model providers...
        },
        // Controller providers, middleware, etc.
    };
}
